    -- ========== 阅读物 ==========
    elfvah_language_book_1 = {
        id       = "elfvah_language_book_1",
        name     = "《伊芙瓦精灵语基础》上",
        category = "阅读物",
        rarity   = "common",
        level    = 1,
        icon     = "image/item_book_readable.png",
        value    = 1,
        desc     = "一本教授伊芙瓦精灵语基础知识的书籍，共三卷。这是上卷。",
        readableText = "……\n\n第三章：字母与元音调和\n\n伊芙瓦精灵语文字传承自远古绿之子民与自然沟通时使用的符文，每个字符代表一个辅音，元音则以附加符号（\"伊泽\"）标注于辅音上方。书写时需遵循\"元音调和\"原则：若单词蕴含愉悦之意（如tl'da树木），元音符号需向上飞扬；若蕴含哀婉之意（如niamo泪水），则笔势下沉。\n\n练习：1）尝试拼写\"星辰\"一词；2）思考\"星辰\"一词的元音调和处理。（注意：学习者需要将自身代入伊芙瓦精灵的思维情景，这种代入是需要反复练习的）\n\n（本教材由伊泽瑞拉学者编纂，禁止用于黑暗咒文书写。）\n\n……",
    },
    elfvah_language_book_2 = {
        id       = "elfvah_language_book_2",
