        category = "阅读物",
        rarity   = "common",
        level    = 1,
        icon     = "image/item_book_readable.png",
        value    = 1,
        desc     = "一本教授伊芙瓦精灵语基础知识的书籍，共三卷。这是中卷。",
        readableText = "……\n\n第五章：名词的复数形式与自然法则\n\n伊芙瓦精灵语的名词复数形态不遵循单一规则，而是与事物本身的\"本质\"相关。凡属于有生命或自然造物者（如树木、动物、星辰）且处于蓬勃生长阶段，常通过添加词尾\"-alda\"成复数；属于无生命或生命力量衰败过程中（如冬天即将枯萎的花、陷入冬眠状态的熊），则多添加词尾\"-dia\"。伊芙瓦精灵对一个生命所蕴含的生命力量的边际变化有着高度敏感。\n\n特例：almon（山)-almolo（群山）；pert（田地）-peryth（广袤平原）\n此等特例是因为古老习惯。\n\n……",
    },
