        readableText = "……\n\n第十二章：介词与方位哲学\n\n伊芙瓦精灵语的介词不仅标示位置，更揭示精灵对空间关系的哲学认知。\"da\"表示\"朝向、为了\"，蕴含目的与归属；而\"vila\"表示\"如同、以…方式\"，常引申出比喻与本质的联结。\"or\"（在……内部），仅用于描述物理上的内外关系；如果要表示抽象的包含关系，必须使用复合形式\"or\"+\"da\"（在……下方），暗示被包裹的\"内在性\"。\n\n（注意：误用\"orda\"可能导致承诺性歧义，表示\"我\"被包含在承诺之中，曾有学徒因此被误解为立下誓言。）\n\n……",
    },

